//! Lucide icons (ISC licence) for the Annotate toolbar, as Rune SVG icons in a 24-unit view box: stroke 2, round
//! caps and joins, drawn in the element's colour (spec 01 AN-UI-195).

use rune::Icon;

const fn lucide(name: &'static str, body: &'static str) -> Icon {
    Icon { name, view: 24.0, body }
}

